import{_ as t,l,o as e,c as r,v as o,p as s,x as i,d as h,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"Levinson 光刻原理","description":"","frontmatter":{"title":"Levinson 光刻原理","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/levinson-litho-book.md","filePath":"litho/levinson-litho-book.md","lastUpdated":1789023840000}'),E={name:"litho/levinson-litho-book.md"};function d(m,a,v,A,B,_){const n=l("Mermaid");return e(),r("div",null,[a[1]||(a[1]=o('<h1 id="levinson-光刻原理" tabindex="-1">Levinson 光刻原理 <a class="header-anchor" href="#levinson-光刻原理" aria-label="Permalink to &quot;Levinson 光刻原理&quot;">​</a></h1><div class="epigraph"><p>教材把扫描仪、胶、套刻、计量和多层工艺写成同一条产线语言；主干课按知识树拆开递进，书则按工程师手头的问题排章。</p><footer>—— Harry J. Levinson, Principles of Lithography, SPIE Press（多版）</footer></div><p>附录对照，不插入主干。<a href="/litho/hopkins-1953-paper">上一课</a>对照了 1953 年的成像核。本篇对照 Levinson 的《光刻原理》：它是产线手册式教材，覆盖波长、RET、套刻、胶、计量与后道分层，<strong>不是</strong>本课程序列的替代目录。主干已按深度优先拆成单课；这里只标书与树的映射，避免把每一课重新从书的第一章写起。High-NA 光学论文对照留给<a href="/litho/vanschoot-high-na-paper">下一课</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>主干禁止百科：后课只补上一课缺口。Levinson 的读者却可能从任意章进入——先看 overlay 再看光学。附录的缺口是：如何引用这本书而不把树打乱。计算光刻专文用 Mack 收逆问题；Levinson 更偏设备、工艺窗、套刻预算和工厂计量。两本教材重叠在瑞利式与 RET，分工不同。</p><p>若把 Levinson 当主干，读者会在每一叶重复「光刻是什么」。本课只对照：书里哪些章对应已经写过的叶，哪些（如工厂组织）树里故意不单列。</p><h3 id="与-mack-的分工" tabindex="-1">与 Mack 的分工 <a class="header-anchor" href="#与-mack-的分工" aria-label="Permalink to &quot;与 Mack 的分工&quot;">​</a></h3><p>Mack, <em>Fundamental Principles of Optical Lithography</em> 更咬空中像、NILS 与胶模型。Levinson 更咬扫描仪使用、套刻、掩模与多层选择。主干成像课序更靠近 Mack；<a href="/litho/beol-wavelength-mix">后道波长分层</a>、<a href="/litho/litho-overlay">套刻</a>、计量课更常点 Levinson。附录同时承认两本，不选唯一圣经。</p><p><span class="marginnote">引用时写书名与出版社即可。不要为教材发明 arXiv 或论文编号。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照表按树来读，不按书的页码背诵。光学与 \\(k_1\\)：对主干 <a href="/litho/rayleigh-litho">rayleigh-litho</a> 与波长台阶。套刻与对准：对 litho-overlay、标记与热源课。胶与 CAR：对 CAR / 衬度课。计量：CD-SEM、OCD、套刻计量。多层与工具选择：对 beol-wavelength-mix。掩模：对二元/相移与掩模厂流程。</p><p>读法：需要产线词汇（on-product overlay、工艺窗、标记）时翻 Levinson；需要成像核与 NILS 时翻 Mack 或 Hopkins。计算光刻专文已经声明不编造内部小时数；Levinson 同样不提供某厂 OPC 产能。</p>',12)),(e(),s(c,null,{default:i(()=>[p(n,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20BOOK%5B%22Levinson%20%E6%95%99%E6%9D%90%22%5D%20--%3E%20OV%5B%22%E5%A5%97%E5%88%BB%20%2F%20%E8%AE%A1%E9%87%8F%20%2F%20%E5%A4%9A%E5%B1%82%22%5D%0A%20%20MACK%5B%22Mack%20%E6%95%99%E6%9D%90%22%5D%20--%3E%20IMG%5B%22%E7%A9%BA%E4%B8%AD%E5%83%8F%20%2F%20NILS%20%2F%20%E8%83%B6%E6%A0%B8%22%5D%0A%20%20HOP%5B%22Hopkins%201953%22%5D%20--%3E%20TCC%5B%22TCC%20%E6%A0%B8%22%5D%0A%20%20TREE%5B%22%E4%B8%BB%E5%B9%B2%E8%AF%BE%E5%BA%8F%22%5D%20--%3E%20SEQ%5B%22%E6%8C%89%E7%BC%BA%E5%8F%A3%E9%80%92%E8%BF%9B%22%5D%0A%20%20BOOK%20--%3E%20MAP%5B%22%E9%99%84%E5%BD%95%E6%98%A0%E5%B0%84%2C%20%E4%B8%8D%E6%8F%92%E5%85%A5%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[h(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<h3 id="版本" tabindex="-1">版本 <a class="header-anchor" href="#版本" aria-label="Permalink to &quot;版本&quot;">​</a></h3><p>书有多版，设备世代会变，原理章相对稳。对照时以原理为准：套刻贡献源、波长不能连续拧、计量定义要声明。具体机型数字以 ASML 当时产品页为准，不要把旧版教材里的步进器规格写成 2026 年的 EXE。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>教材的机制是<strong>横向索引</strong>：同一条产线问题（窗口不够）会同时指向照明、胶、刻蚀和计量。主干的机制是<strong>纵向缺口</strong>：上一课留下什么，本课只补什么。两者合用时，书负责防止工程师只记得自己那一课，树负责防止每篇都从 Rayleigh 起笔。</p><p>后道分层是例子：Levinson 用专章讲不是所有层都用最短波长；主干把它收成 beol-wavelength-mix 一叶，接在接触孔之后。书不会按 GAA 再 ALD 再 DSA 的树顺序排——那是课程，不是教材目录。套刻章与对准/热源三课的关系同样：书把贡献源写在一处，树把它拆成策略、掩模热、晶圆热三叶，避免一课吞并三课。</p><p><span class="marginnote">SPIE Press 的教材不是期刊论文。出处写书，不要编 DOI 去冒充 1953 那种论文。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本篇不插入主干，不把 Levinson 的章序改写成 sidebar。不摘录大段原文。不把书中某张过时的节点表当成 2026 年路线图。下一篇 van Schoot 是 High-NA 光学的公开论文对照，对应 <a href="/litho/asml-high-na">asml-high-na</a> 那一叶，仍是附录。</p><p><span class="marginnote">出处：H. J. Levinson, <em>Principles of Lithography</em>, SPIE Press。与 Mack 2007 对照使用；均不替代课程序列。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>附录对照教材：产线词汇与多层工艺，不插入深度优先课序。</li><li>与 Mack（成像核）、Hopkins（TCC）分工，不选唯一课本。</li><li>引用原理，不把旧版机型表当现行规格。</li><li>High-NA 公开论文下一篇。</li><li>出处：Levinson, <em>Principles of Lithography</em>, SPIE Press。</li></ul>',11))])}const g=t(E,[["render",d]]);export{f as __pageData,g as default};
